namespace EntMap.Constants
{
    public static class GlobalSourceGeneratorConstants
    {
        public static string MapContextClassName => "MapContext";
        
        public static string GetMapContextSource => $$"""
          // EntMapGenerate <auto-generated />
          #nullable enable

          namespace {{GlobalMapperConstants.MainNamespace}}
          {
              internal class {{MapContextClassName}}<TSource, TTarget>
              {
                  public TSource Source { get; }
                  public TTarget Target { get; }
                  public {{MapContextClassName}}(TSource source, TTarget target) { Source = source; Target = target; }
              }
          }
          """;

        public static string MappingContextClassName => "MappingContext";
        
        public static string GetMappingContextSource => $$"""
          // EntMapGenerate <auto-generated />
          #nullable enable

          namespace {{GlobalMapperConstants.MainNamespace}}
          {
              internal static class {{MappingContextClassName}}
              {
                  private static readonly System.Threading.AsyncLocal<System.Collections.Generic.Dictionary<object, object>?> _cache = new();
                  public static System.Collections.Generic.Dictionary<object, object> Cache => _cache.Value ??= new();
                  public static void Clear() => _cache.Value = null;
              }
          }
          """;
        
        public static string EntMappingProfileClassName => "EntMappingProfile";
        
        public static string GetEntMappingProfileSource(string namespaceName) => $$"""
            // EntMapGenerate <auto-generated />
            #nullable enable
            using System;
            using System.Linq;

            namespace {{namespaceName}}.Profile
            {
                // Класс-профиль
                public abstract class {{EntMappingProfileClassName}}
                {
                    protected MemberConfigurationExpression<TSource, TTarget> CreateMap<TSource, TTarget>()
                    {
                        return new MemberConfigurationExpression<TSource, TTarget>();
                    }
                }
    
                // Инструмент для цепочки вызовов (Fluent API), который C# разрешает использовать как statement
                public interface IMappingExpression<TSource, TTarget>
                {
                    IMappingExpression<TSource, TTarget> ForMember<TValue>(
                        System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                        Func<TSource, TValue> mapFrom);
                }
    
                public class MemberConfigurationExpression<TSource, TTarget> : IMappingExpression<TSource, TTarget>
                {
                    public IMappingExpression<TSource, TTarget> ForMember<TValue>(
                        System.Linq.Expressions.Expression<Func<TTarget, TValue>> destinationMember, 
                        Func<TSource, TValue> mapFrom)
                    {
                        return this;
                    }
                }   
            }
            """;
    }
}
